        /** @enum {string} */
        StepFormat: "STRUCTURED" | "GHERKIN";
        /** @enum {string} */
        StatusKind: "PASSED" | "FAILED" | "BLOCKED" | "SKIPPED" | "UNTESTED" | "RETEST";
